/** Language preference and controlled DOM sentence replacement. Dictionaries have no HTML.
 * Access through workspace.locale; English fallback is visible rather than invented translation. */
class LocaleService {
  constructor(){try{this.language=localStorage.getItem('vesa.ppm.language')||'en'}catch{this.language='en'}if(!['en','bn','hi','ta'].includes(this.language))this.language='en'}
  set(language){if(!['en','bn','hi','ta'].includes(language))return;this.language=language;try{localStorage.setItem('vesa.ppm.language',language)}catch{}document.documentElement.lang=language}
  checkpoint(id,english){return PPM_SENTENCES[id]?.[this.language]||english}
  sentence(key,english){return PPM_SENTENCES[key]?.[this.language]||english}
}

